# Count flags per command in docker.toml
echo "=== DOCKER ===" 
awk '
/^\[\[command\]\]/ { in_cmd=1; next }
/^\[\[flag\]\]/ { in_flag=1; in_cmd=0; next }
in_cmd && /^path =/ {
  cmd = $0
  gsub(/^path = "/, "", cmd)
  gsub(/"$/, "", cmd)
  current_cmd = cmd
  cmd_count[cmd] = 0
}
in_flag && /^applies_to =/ {
  cmd = $0
  gsub(/^applies_to = "/, "", cmd)
  gsub(/"$/, "", cmd)
  cmd_count[cmd]++
}
END {
  for (cmd in cmd_count) {
    if (cmd_count[cmd] > 0) {
      print cmd_count[cmd] " | " cmd
    }
  }
}
' tools/docker.toml | sort -rn | head -15

